const itemCondition = computed(() => ({ new: 'https://schema.org/NewCondition', used: 'https://schema.org/UsedCondition', refurbished: 'https://schema.org/RefurbishedCondition' }[props.product.condition] || 'https://schema.org/NewCondition'));
const schema = computed(() => ({ '@context': 'https://schema.org', '@graph': [{ '@type': 'Product', '@id': `${canonical.value}#product`, mainEntityOfPage: { '@id': `${canonical.value}#webpage` }, name: props.product.name, image: schemaImages.value, description: props.product.plain_description || props.product.short_description, sku: props.product.sku, gtin: props.product.gtin || undefined, mpn: props.product.mpn || undefined, color: props.product.color || undefined, size: props.product.size || undefined, brand: props.product.brand ? { '@type': 'Brand', name: props.product.brand.name } : undefined, offers: { '@type': 'Offer', url: canonical.value, priceCurrency: page.props.store.currency, price: props.product.current_price, availability: props.product.in_stock ? 'https://schema.org/InStock' : 'https://schema.org/OutOfStock', itemCondition: itemCondition.value, seller: { '@id': `${page.props.store.url}/#store` } } }, { '@type': 'WebPage', '@id': `${canonical.value}#webpage`, url: canonical.value, name: props.product.meta_title || props.product.name, primaryImageOfPage: props.product.image_metadata ? { ...props.product.image_metadata, contentUrl: absoluteUrl(props.product.image_metadata.contentUrl), url: absoluteUrl(props.product.image_metadata.url || props.product.image_metadata.contentUrl) } : absoluteUrl(props.product.image_url), mainEntity: { '@id': `${canonical.value}#product` }, publisher: { '@id': `${page.props.store.url}/#store` } }, { '@type': 'BreadcrumbList', itemListElement: [{ '@type': 'ListItem', position: 1, name: 'Home', item: page.props.store.url }, { '@type': 'ListItem', position: 2, name: 'Shop', item: absoluteUrl('/shop') }, ...(props.product.category ? [{ '@type': 'ListItem', position: 3, name: props.product.category.name, item: absoluteUrl(`/shop?category=${encodeURIComponent(props.product.category.slug)}`) }] : []), { '@type': 'ListItem', position: props.product.category ? 4 : 3, name: props.product.name, item: canonical.value }] }] }));
