n><div class="flex flex-wrap items-center gap-2"><span v-if="product.category" class="rounded-[8px] bg-prinx-50 px-2.5 py-1 text-xs font-extrabold text-prinx-700">{{ product.category.name }}</span><span :class="['rounded-[8px] px-2.5 py-1 text-xs font-extrabold',product.in_stock?'bg-emerald-50 text-emerald-700':'bg-red-50 text-red-700']">{{ product.in_stock?'In stock':'Out of stock' }}</span></div><p class="mt-5 section-kicker">{{ product.brand?.name || 'Prinx Electronics' }}</p><h1 class="mt-3 text-3xl font-black tracking-tight text-slate-950 sm:text-4xl lg:text-[42px] lg:leading-[1.12]">{{ product.name }}</h1><p class="mt-3 text-sm font-semibold text-slate-500">SKU: {{ product.sku }}</p><div class="mt-6 flex flex-wrap items-end gap-x-3 gap-y-1"><span class="text-3xl font-black text-slate-950 sm:text-4xl">{{ money(product.current_price) }}</span><span v-if="Number(product.current_price)<Number(product.price)" class="pb-1 text-lg font-semibold text-slate-400 line-through">{{ money(product.price) }}</span></div><p class="mt-6 text-base font-medium leading-7 text-slate-600 sm:text-lg sm:leading-8">{{ product.short_description }}</p><div class="mt-7 grid grid-cols-2 gap-3"><div class="rounded-[8px] border border-slate-200 bg-white p-4"><span class="text-[11px] font-black uppercase tracking-wider text-slate-400">Condition</span><b class="mt-1 block capitalize text-slate-900">{{ product.condition }}</b></div><div class="rounded-[8px] border border-slate-200 bg-white p-4"><span class="text-[11px] font-black uppercase tracking-wider text-slate-400">Warranty</span><b class="mt-1 block text-slate-900">{{ product.warranty || 'Contact store' }}</b></div><div class="rounded-[8px] border border-slate-200 bg-white p-4"><span class="text-[11px] font-black uppercase tracking-wider text-slate-400">Payment</span><b class="mt-1 block text-slate-900">Confirmed on order</b></div><div class="rounded-[8px] border border-slate-200 bg-white p-4"><span class="text-[11px] font-black uppercase